    try:
        result = terminal(command=cmd, timeout=10)
        return result.get('output', '').strip()
    except Exception as e:
        return f"Error: {str(e)}"

def get_hermes_home():
    home = os.environ.get('HERMES_HOME', os.path.expanduser('~/.hermes'))
    return home

def check_openclaw():
    ps_output = run_cmd("ps aux | grep -i openclaw | grep -v grep")
    task_dir = os.path.expanduser('~/openclaw/tasks')
    task_count = 0
    if os.path.exists(task_dir):
        try:
            task_count = len([f for f in os.listdir(task_dir) if f.endswith('.json') or f.endswith('.yaml')])
        except:
            pass
    return ps_output, task_count

def check_hermes_health():
    doctor = run_cmd("hermes doctor")
    gateway = run_cmd("hermes gateway status")
    cron = run_cmd("hermes cron list")
    memory = run_cmd("hermes memory status")
    return doctor, gateway, cron, memory

def check_book_progress():
    home = os.path.expanduser('~')
    possible = [
        os.path.join(home, 'books', 'Second Generation'),
        os.path.join(home, 'Documents', 'Books', 'Second Generation'),
        os.path.join(home, 'Second Generation'),
        os.path.join(home, 'books', 'Second_Generation'),
        os.path.join(home, 'Second_Generation')
    ]
    book_dir = None
    for p in possible:
        if os.path.exists(p):
            book_dir = p
            break
    if not book_dir:
        return "No Second Generation book directory found"
    # Check for book-sources directory (may be nested)
    sources_dir = os.path.join(book_dir, 'book-sources')
    if not os.path.exists(sources_dir):
        # Maybe it's directly in book-sources/Second_Generation?
        alt = os.path.join(book_dir, 'book-sources', 'Second_Generation')
        if os.path.exists(alt):
            sources_dir = alt
        else:
            return f"Book directory found at {book_dir} but no book-sources subdirectory"
    # Count chapter files
    chapter_files = []
    try:
        for f in os.listdir(sources_dir):
            if f.startswith('Chapter_') and f.endswith('.md'):
                chapter_files.append(f)
    except Exception as e:
        return f"Error listing chapters: {str(e)}"
    total_chapters = len(chapter_files)
    # Try to read specification to get expected total
    spec_file = os.path.join(book_dir, 'SPECIFICATION.md')
    expected = "unknown"
    if os.path.exists(spec_file):
        try:
            content = read_file(path=spec_file, limit=200)['content']
            import re
            match = re.search(r'(\d+)\s*chapters?', content, re.I)
            if match:
                expected = match.group(1)
        except Exception as e:
            pass
    return f"Found {total_chapters} chapters (expected ~{expected}) in {sources_dir}"

